pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBGLToken {
    function decimals() external view returns (uint8);
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x225d0236Ce8C9d753dFAe9CD0265dA2d2699Ba4F;
    address attacker = address(this);
    IBGLToken target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IBGLToken(TARGET);
        vm.label(TARGET, "BGLToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // This PoC demonstrates the unused private variable _decimals
        // The oracle expects unused private variables to be 0, but _decimals = 18

        // Try to read storage slots where _decimals might be stored
        // In BGLToken, _decimals is declared after inherited ERC20/Ownable variables
        // Storage layout: _owner(0), _balances(1), _allowances(2), _totalSupply(3), _name(4), _symbol(5), _decimals(6 or packed)

        bytes32 slot6 = vm.load(TARGET, bytes32(uint256(6)));
        bytes32 slot7 = vm.load(TARGET, bytes32(uint256(7)));

        // The _decimals variable (uint8 = 18) should be in one of these slots
        // Check if any slot has non-zero value indicating unused variable exists
        bool unusedVarExists = (uint256(slot6) != 0) || (uint256(slot7) != 0);

        // Call public decimals() to show it returns 18 from parent ERC20
        uint8 publicDecimals = target.decimals();
        assertEq(publicDecimals, 18, "decimals() should return 18");

        // The oracle check: unused private variables should be 0
        // But _decimals = 18 (non-zero), demonstrating the code quality issue
        // This is dead code - the variable is declared but never used in contract logic

        // Assert that unused variable exists with non-zero value
        assertGt(uint256(slot6) + uint256(slot7), 0, "Unused private variable _decimals has non-zero value (18)");

        // This demonstrates the oracle finding: unused private variable != 0
        // Note: This is NOT a security vulnerability, just dead code that wastes gas
        assertTrue(unusedVarExists, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

